import React, { useRef, useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import SalonCard from "../../components/common/SalonCard";
import TabBar from "../../components/common/TabBar";
import oliviaSalon from "../../images/oliviaSalon.jpg";
import promotionHeader from "../../images/promotionHeader.png";

const offers = [
  { id: 1, banner: promotionHeader },
  { id: 2, banner: promotionHeader },
];

// ===== Styled Components =====
const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 20px 3%;
  box-sizing: border-box;
`;

const WelcomeText = styled.h1`
  font-family: "Inter", sans-serif;
  font-size: 48px;
  font-weight: 700;
  color: #4A5074;
  margin: 40px 0 30px;
`;

const PromoBanner = styled.div`
  width: 350px;
  min-width: 350px;
  height: 220px;
  border-radius: 12px;
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
`;

const BannerImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
`;

const BookNowButton = styled.button`
  position: absolute;
  bottom: 20px;
  left: 20px;
  background-color: #0b1c36;
  color: white;
  font-size: 16px;
  font-weight: 500;
  padding: 10px 18px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: 0.2s ease;
  &:hover {
    opacity: 0.9;
  }
`;

const CategoryHeader = styled.div`
  background-color: #fff;
  display: inline-block;
  padding: 8px 18px;
  border-radius: 10px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
  margin-bottom: 16px;
`;

const SectionTitle = styled.h2`
  font-size: 22px;
  font-weight: 700;
  color: #4A5074;
  margin: 0;
`;

const ScrollWrapper = styled.div`
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  margin-bottom: 40px;
`;

const HorizontalScroll = styled.div`
  display: flex;
  gap: 18px;
  overflow-x: auto;
  scroll-behavior: smooth;
  width: 100%;
  padding-bottom: 14px;
`;

const ScrollButton = styled.div<{ side: "left" | "right" }>`
  width: 45px;
  height: 45px;
  border-radius: 50%;
  background-color: white;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: absolute;
  ${(p) => (p.side === "left" ? "left: -22px;" : "right: -22px;")}
  z-index: 5;
  transition: 0.2s ease;
  &:hover {
    transform: scale(1.05);
    background-color: #f8f8f8;
  }
`;

const ArrowIcon = ({ direction }: { direction: "left" | "right" }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="22"
    height="22"
    fill="none"
    stroke="#000"
    strokeWidth="2"
    viewBox="0 0 24 24"
    style={{
      transform: direction === "left" ? "rotate(180deg)" : "none",
    }}
  >
    <path d="M9 18l6-6-6-6" />
  </svg>
);

// ===== Component =====
const HomePage: React.FC = () => {
  const navigate = useNavigate();

  const salons = [
    {
      id: "hair-avenue",
      image: oliviaSalon,
      name: "Hair Avenue",
      distance: "2.3 km",
      location: "No 03, Kadalana Road, Kadalana, Moratuwa",
      rating: 4.7,
      reviews: 312,
      hours: "9AM - 10PM, Mon - Sun",
      description:
        "Hair Avenue provides expert haircuts, styling, along with services like facials, cleanups, skincare and makeup.",
      services: [
        { id: 1, name: "Hair Cut", price: "22 BD", duration: "30 Mins" },
        { id: 2, name: "Hair Wash", price: "6 BD", duration: "30 Mins" },
        { id: 3, name: "Beard Trim", price: "5 BD", duration: "20 Mins" },
      ],
      categories: ["Hair Cut", "Hair Styling", "Hair Treatments", "Combo", "Nails"],
    },
    // ... keep your other salons
  ];

  const scrollRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [scrollPositions, setScrollPositions] = useState<number[]>([]);

  const CARDS_PER_PAGE = 5;
  const CARD_WIDTH = 255 + 18;

  const handleScroll = (index: number, direction: "left" | "right") => {
    const container = scrollRefs.current[index];
    if (!container) return;

    const delta =
      direction === "right"
        ? CARD_WIDTH * CARDS_PER_PAGE
        : -CARD_WIDTH * CARDS_PER_PAGE;

    container.scrollBy({ left: delta, behavior: "smooth" });

    setScrollPositions((prev) => {
      const updated = [...prev];
      const newPos =
        (updated[index] || 0) + (direction === "right" ? 1 : -1);
      updated[index] = Math.max(0, newPos);
      return updated;
    });
  };

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        <WelcomeText>Welcome Back, Enid!</WelcomeText>

        {/* ===== OFFERS CAROUSEL ===== */}
        <SectionTitle>Special Offers</SectionTitle>
        <HorizontalScroll>
          {offers.map((offer) => (
            <PromoBanner key={offer.id}>
              <BannerImage src={offer.banner} alt="Offer" />
              <BookNowButton>Book Now</BookNowButton>
            </PromoBanner>
          ))}
        </HorizontalScroll>

        {/* ===== Salon Categories ===== */}
        {["Trending Now", "Near You", "For Her", "For Him"].map(
          (category, index) => {
            const start = (scrollPositions[index] || 0) * CARDS_PER_PAGE;
            const visibleSalons = salons.slice(start, start + CARDS_PER_PAGE);
            const hasMore = start + CARDS_PER_PAGE < salons.length;
            const canScrollBack = start > 0;

            return (
              <div key={category}>
                <CategoryHeader>
                  <SectionTitle>{category}</SectionTitle>
                </CategoryHeader>

                <ScrollWrapper>
                  {canScrollBack && (
                    <ScrollButton
                      side="left"
                      onClick={() => handleScroll(index, "left")}
                    >
                      <ArrowIcon direction="left" />
                    </ScrollButton>
                  )}

                  <HorizontalScroll
                    ref={(el) => {
                      scrollRefs.current[index] = el;
                    }}
                  >
                    {visibleSalons.map((salon) => (
                      <SalonCard
                        key={`${category}-${salon.id}`}
                        id={salon.id}
                        image={salon.image}
                        name={salon.name}
                        distance={salon.distance}
                        location={salon.location}
                        rating={salon.rating}
                        reviews={salon.reviews}
                        onClick={() =>
                          navigate(`/business/${salon.id}`, { state: salon })
                        }
                      />
                    ))}
                  </HorizontalScroll>

                  {hasMore && (
                    <ScrollButton
                      side="right"
                      onClick={() => handleScroll(index, "right")}
                    >
                      <ArrowIcon direction="right" />
                    </ScrollButton>
                  )}
                </ScrollWrapper>
              </div>
            );
          }
        )}
      </ContentWrapper>
    </PageWrapper>
  );
};

export default HomePage;
